package io.github.baeseungwon1010.officecanvas.pptx

import io.github.baeseungwon1010.officecanvas.slide.*
import org.junit.Assert.*
import org.junit.Test
import java.io.File

/**
 * charts.pptx is generated by tools/make_chart_deck.py: one chart per slide
 * (clustered columns, stacked bars, a line, a pie, a doughnut). Charts are drawn
 * as ordinary shapes, so these check the shapes they become.
 */
class ChartTest {

    private val deck by lazy {
        PptxParser.parse(File(javaClass.classLoader!!.getResource("pptx_samples/charts.pptx")!!.toURI()))
    }

    private fun shapes(slide: Int) = deck.slides[slide].elements.filterIsInstance<Element.Shape>()
    private fun texts(slide: Int) = shapes(slide).mapNotNull { it.text?.paragraphs?.joinToString("\n") { p -> p.plainText } }
    /** Rectangles of [color] standing on the axis (leaving out the legend's color keys below it). */
    private fun bars(slide: Int, color: Int): List<Element.Shape> {
        val rects = shapes(slide).filter { it.geometry == "rect" }
        val axis = rects.groupBy { it.box.y + it.box.h }.maxBy { it.value.size }.key
        return rects.filter { it.fillArgb == color && it.box.y + it.box.h == axis }
    }

    @Test
    fun `clustered columns stand on the axis in proportion to their values`() {
        val sales = bars(0, 0xFF1F9E89.toInt())
        val goal = bars(0, 0xFF98A2B3.toInt())
        assertEquals(3, sales.size)
        assertEquals(3, goal.size)
        // The value axis is fixed at 0..100, so heights go 20 : 40 : 60, all from one baseline.
        val unit = sales[0].box.h / 20.0
        assertEquals(40 * unit, sales[1].box.h.toDouble(), unit)
        assertEquals(80 * unit, goal[2].box.h.toDouble(), unit)
        assertEquals(1, (sales + goal).map { it.box.y + it.box.h }.distinct().size)
        // Each category's pair sits side by side, the first series on the left.
        for (i in 0..2) assertEquals((sales[i].box.x + sales[i].box.w).toDouble(), goal[i].box.x.toDouble(), sales[i].box.w / 50.0)
    }

    @Test
    fun `title, value labels, axis labels and legend are text`() {
        val t = texts(0)
        assertTrue(t.toString(), "분기별 판매" in t)
        for (label in listOf("20", "30", "40", "50", "60", "80", "1분기", "2분기", "3분기", "판매", "목표", "0", "100")) {
            assertTrue("$label in $t", label in t)
        }
        val title = shapes(0).first { it.text?.paragraphs?.first()?.plainText == "분기별 판매" }
        assertEquals(HAlign.CENTER, title.text!!.paragraphs.first().align)
        // Gridlines at each step of the value axis.
        assertTrue(shapes(0).count { it.geometry == "line" } >= 5)
    }

    @Test
    fun `stacked bars run end to end along the value axis`() {
        val segments = shapes(1).filter { it.geometry == "rect" }
        assertEquals(6, segments.size) // no legend
        // Category A is drawn at the bottom; its segments are 1, 3 and 5 long.
        val a = segments.filter { s -> s.box.y == segments.maxOf { it.box.y } }.sortedBy { it.box.x }
        assertEquals(3, a.size)
        assertEquals((a[0].box.x + a[0].box.w).toDouble(), a[1].box.x.toDouble(), 2.0)
        assertEquals(3.0 * a[0].box.w, a[1].box.w.toDouble(), a[0].box.w * 0.02)
        assertEquals(5.0 * a[0].box.w, a[2].box.w.toDouble(), a[0].box.w * 0.02)
        // Three series in the theme's first three accents.
        assertEquals(3, segments.map { it.fillArgb }.distinct().size)
    }

    @Test
    fun `a line goes through its points, with markers`() {
        val line = shapes(2).single { it.outline != null && it.fillArgb == null }
        val points = line.outline!!.filter { it is PathOp.MoveTo || it is PathOp.LineTo }
        assertEquals(4, points.size)
        val ys = points.map { (it as? PathOp.MoveTo)?.y ?: (it as PathOp.LineTo).y }
        // 10, 30, 20, 40: higher values are higher up.
        assertTrue(ys.toString(), ys[1] < ys[0] && ys[2] > ys[1] && ys[3] < ys[1])
        assertEquals(4, shapes(2).count { it.geometry == "ellipse" })
        // One series and no title element: the series name is the title.
        assertTrue("방문" in texts(2))
    }

    @Test
    fun `pie slices take point colors and show percentages`() {
        val slices = shapes(3).filter { it.outline != null }
        assertEquals(3, slices.size)
        assertEquals(0xFFC00000.toInt(), slices[1].fillArgb)
        assertEquals(3, slices.map { it.fillArgb }.distinct().size)
        for (p in listOf("50%", "30%", "20%")) assertTrue("$p in ${texts(3)}", p in texts(3))
    }

    @Test
    fun `a doughnut is ring segments`() {
        val segments = shapes(4).filter { it.outline != null }
        assertEquals(2, segments.size)
        // A ring segment has two arcs, outside and inside, joined by lines.
        assertTrue(segments.all { s -> s.outline!!.count { it is PathOp.LineTo } == 1 })
    }

    @Test
    fun `numbers are formatted the way the format code says`() {
        assertEquals("12.3", ChartParser.formatNumber(12.30, "General"))
        assertEquals("52", ChartParser.formatNumber(52.0, null))
        assertEquals("12.3", ChartParser.formatNumber(12.34, "0.0"))
        assertEquals("1,234,567", ChartParser.formatNumber(1234567.0, "#,##0"))
        assertEquals("26%", ChartParser.formatNumber(0.256, "0%"))
        assertEquals("$1,234.50", ChartParser.formatNumber(1234.5, "\"$\"#,##0.00"))
        assertEquals("5건", ChartParser.formatNumber(5.0, "0\"건\""))
    }
}
